import argparse
from operations import Calculator

def main():
    parser = argparse.ArgumentParser(description="CLI Calculator")
    parser.add_argument("--op", choices=['add', 'subtract', 'multiply', 'divide'], required=True)
    parser.add_argument("a", type=float)
    parser.add_argument("b", type=float)

    args = parser.parse_args()
    calc = Calculator()

    try:
        if args.op == 'add':
            result = calc.add(args.a, args.b)
        elif args.op == 'subtract':
            result = calc.subtract(args.a, args.b)
        elif args.op == 'multiply':
            result = calc.multiply(args.a, args.b)
        elif args.op == 'divide':
            result = calc.divide(args.a, args.b)

