        """Clears all logged history."""
        self._history = []

    def evaluate(self, expression: str) -> float:
        """
        Parses and evaluates a string expression using AST to respect precedence.
        Maps operations back to internal methods to preserve audit trail.
        """
        operators = {
            ast.Add: self.add,
            ast.Sub: self.subtract,
            ast.Mult: self.multiply,
            ast.Div: self.divide,
            ast.Pow: self.power,
            ast.Mod: self.modulo
        }

        def _eval(node):
            if isinstance(node, ast.Constant):
                return float(node.value)
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
